export function enrichLessons(lessons: Lesson[]): Lesson[] {
  return lessons.map((lesson) => {
    const replacement = expanded[lesson.id]
    const supplement = supplements[lesson.id]
    const extension = readingExtensions[lesson.id]
    if (!replacement && !supplement && !extension) return lesson
    const smp = { ...lesson.smp, ...(replacement?.smp ?? {}) }
    const sma = { ...lesson.sma, ...(replacement?.sma ?? {}) }
    if (supplement) {
      smp.reading = `${smp.reading}\n\n${supplement.smp.reading}`
      smp.translation = `${smp.translation}\n\n${supplement.smp.translation}`
      sma.reading = `${sma.reading}\n\n${supplement.sma.reading}`
      sma.translation = `${sma.translation}\n\n${supplement.sma.translation}`
    }
    if (extension) {
      smp.reading = `${smp.reading}\n\n${extension.smp.reading}`
      smp.translation = `${smp.translation}\n\n${extension.smp.translation}`
      sma.reading = `${sma.reading}\n\n${extension.sma.reading}`
      sma.translation = `${sma.translation}\n\n${extension.sma.translation}`
    }
    smp.audioText = smp.reading
    sma.audioText = sma.reading
    return { ...lesson, smp, sma }
  })
}
